+      top: 16px;
+      transform: translateY(-160%);
+      padding: 10px 14px;
+      border-radius: 999px;
+      background: #f8fafc;
+      color: #0f172a;
+      font-weight: 700;
+      text-decoration: none;
+      transition: transform 0.2s ease;
+    }
+
+    .skip-link:focus {
+      transform: translateY(0);
+    }
+
+    main {
+      width: min(100%, 460px);
+    }
+
+    .card {
+      padding: 32px;
+      border: 1px solid var(--panel-border);
+      border-radius: 24px;
+      background: var(--panel);
+      backdrop-filter: blur(18px);
+      box-shadow: var(--shadow);
+    }
+
+    h1 {
+      margin: 0 0 12px;
+      font-size: clamp(1.8rem, 3vw, 2.2rem);
+      line-height: 1.1;
+    }
+
+    .intro {
+      margin: 0 0 24px;
+      color: var(--muted);
+      line-height: 1.6;
+    }
+
+    form {
+      display: grid;
+      gap: 20px;
+    }
+
+    .form-field {
+      display: grid;
+      gap: 10px;
+      padding: 18px;
+      border: 1px solid rgba(125, 211, 252, 0.14);
+      border-radius: 18px;
+      background: rgba(15, 23, 42, 0.72);
+    }
+
+    .checkbox-row {
+      display: flex;
+      align-items: flex-start;
+      gap: 12px;
+    }
+
+    input[type="checkbox"] {
+      width: 1.15rem;
+      height: 1.15rem;
+      margin: 0.15rem 0 0;
+      accent-color: var(--accent-strong);
+      flex: none;
+    }
+
+    label {
+      line-height: 1.5;
+      font-weight: 600;
+    }
+
+    .required-mark {
+      color: #facc15;
+      font-weight: 700;
+    }
+
+    .helper-text,
+    .error-text,
+    .status-text {
+      margin: 0;
+      font-size: 0.95rem;
+      line-height: 1.5;
+    }
+
+    .helper-text {
+      color: var(--muted);
+    }
+
+    .error-text {
+      color: var(--danger);
+    }
+
+    .status-text {
+      min-height: 1.5em;
+      color: #bef264;
+    }
+
+    button {
+      padding: 0.9rem 1.2rem;
+      border: 0;
+      border-radius: 14px;
+      background: linear-gradient(135deg, #38bdf8, #0ea5e9);
+      color: #082f49;
+      font: inherit;
+      font-weight: 800;
+      cursor: pointer;
+      box-shadow: 0 12px 24px rgba(14, 165, 233, 0.25);
+    }
+
+    a:focus-visible,
+    button:focus-visible,
+    input:focus-visible {
+      outline: 3px solid #f8fafc;
+      outline-offset: 3px;
+    }
+
+    input[aria-invalid="true"] {
+      outline: 2px solid var(--danger);
+      outline-offset: 3px;
+    }
+
+    @media (max-width: 480px) {
+      body {
+        padding: 16px;
+      }
+
+      .card {
+        padding: 24px;
+      }
+    }
+
+    @media (forced-colors: active) {
+      .card,
+      .form-field,
+      button,
+      .skip-link {
+        border: 1px solid CanvasText;
+        box-shadow: none;
+      }
+
+      button {
+        background: ButtonFace;
+        color: ButtonText;
+      }
+    }
+  </style>
+</head>
+<body>
+  <a class="skip-link" href="#main-content">Skip to main content</a>
+  <main id="main-content" tabindex="-1"></main>
+  <script>
+    const root = document.getElementById("main-content");
+
+    function FormField(content) {
+      return '<div class="form-field">' + content + "</div>";
+    }
+
+    function ConsentCheckbox() {
+      return FormField(
+        '<div class="checkbox-row">' +
+          '<input id="termsConsent" name="termsConsent" type="checkbox" required aria-describedby="consent-help">' +
+          '<label for="termsConsent">I agree to the <a href="#" aria-label="terms of use">terms of use</a> <span class="required-mark" aria-hidden="true">*</span></label>' +
+        "</div>" +
+        '<p id="consent-help" class="helper-text">Required to continue with submission.</p>' +
+        '<p id="consent-error" class="error-text" hidden>Error: You must agree to the terms of use before submitting.</p>'
+      );
+    }
+
+    function SubmitButton() {
+      return '<button type="submit">Submit consent</button>';
+    }
+
+    function App() {
+      return (
+        '<section class="card" aria-labelledby="page-title">' +
+          '<h1 id="page-title">Terms confirmation</h1>' +
+          '<p class="intro">Please review the required consent below before continuing.</p>' +
+          '<form id="consent-form" novalidate>' +
+            ConsentCheckbox() +
+            SubmitButton() +
+            '<p id="form-status" class="status-text" aria-live="polite"></p>' +
+          "</form>" +
+        "</section>"
+      );
+    }
+
+    root.innerHTML = App();
+
+    const form = document.getElementById("consent-form");
+    const checkbox = document.getElementById("termsConsent");
+    const error = document.getElementById("consent-error");
+    const status = document.getElementById("form-status");
+
+    function setConsentValidity(isValid) {
+      checkbox.setAttribute("aria-describedby", isValid ? "consent-help" : "consent-help consent-error");
+      checkbox.setAttribute("aria-invalid", String(!isValid));
+      error.hidden = isValid;
+    }
+
+    setConsentValidity(true);
+
+    checkbox.addEventListener("change", () => {
+      if (checkbox.checked) {
+        setConsentValidity(true);
+        status.textContent = "";
+      }
+    });
+
+    form.addEventListener("submit", (event) => {
+      event.preventDefault();
+
+      if (!checkbox.checked) {
+        setConsentValidity(false);
+        status.textContent = "";
+        checkbox.focus();
+        return;
+      }
+
+      setConsentValidity(true);
+      status.textContent = "Consent recorded. You can continue.";
+    });
+  </script>
+</body>
+</html>
*** End Patch
