    const root = document.getElementById("main-content");

    function FormField(content) {
      return '<div class="form-field">' + content + "</div>";
    }

    function ConsentCheckbox() {
      return FormField(
        '<div class="checkbox-row">' +
          '<input id="termsConsent" name="termsConsent" type="checkbox" required aria-describedby="consent-help">' +
          '<label for="termsConsent">I agree to the terms of use <span class="required-mark" aria-hidden="true">*</span></label>' +
        "</div>" +
        '<p id="consent-help" class="helper-text">Required to continue.</p>' +
        '<p id="consent-error" class="error-text" hidden>Error: You must agree to the terms of use before submitting.</p>'
      );
    }

    function SubmitButton() {
      return '<button type="submit">Submit consent</button>';
    }

    function App() {
      return (
        '<section class="card" aria-labelledby="page-title">' +
          '<h1 id="page-title">Terms confirmation</h1>' +
          '<p class="intro">Please review the required consent below before continuing.</p>' +
          '<p class="required-note"><span class="required-mark" aria-hidden="true">*</span> Required field</p>' +
          '<form id="consent-form" novalidate>' +
            ConsentCheckbox() +
            SubmitButton() +
            '<p id="form-status" class="status-text" role="status" aria-live="polite"></p>' +
          "</form>" +
        "</section>"
      );
    }

    root.innerHTML = App();

    const form = document.getElementById("consent-form");
    const checkbox = document.getElementById("termsConsent");
    const error = document.getElementById("consent-error");
    const status = document.getElementById("form-status");

    function setConsentValidity(isValid) {
      checkbox.setAttribute("aria-describedby", isValid ? "consent-help" : "consent-help consent-error");
      if (isValid) {
        checkbox.removeAttribute("aria-invalid");
        checkbox.removeAttribute("aria-errormessage");
      } else {
        checkbox.setAttribute("aria-invalid", "true");
        checkbox.setAttribute("aria-errormessage", "consent-error");
      }
      error.hidden = isValid;
    }

    setConsentValidity(true);

    checkbox.addEventListener("change", () => {
      if (checkbox.checked) {
        setConsentValidity(true);
        status.textContent = "";
      }
    });

    form.addEventListener("submit", (event) => {
      event.preventDefault();

      if (!checkbox.checked) {
        setConsentValidity(false);
        status.textContent = "";
        checkbox.focus();
        return;
      }

      setConsentValidity(true);
      status.textContent = "Consent recorded. You can continue.";
    });
  </script>
</body>
</html>
